141	export function workerEvidenceKey(state: AgentState): string {
142	  const evidence = state.evidence;
143	  const validation = evidence?.validation;
144	  return createHash('sha256').update(JSON.stringify({
145	    task: state.task,
146	    revision: evidence?.revision ?? 0,
147	    validation: validation ? {
148	      generation: validation.generation,
149	      script: validation.script,
150	      exitCode: validation.exitCode,
151	      timedOut: validation.timedOut,
152	      passed: validation.passed,
153	      summary: validation.summary,
154	    } : null,
155	  })).digest('hex');
156	}
