671	                    ? `New ${state.evidence.lastRevisionSource ?? 'repository'} evidence after a failed worker.`
672	                    : 'Approved worker request after prior failure.'
673	                : 'Approved worker request.',
674	        },
675	      } : {}),
676	    });
677	    state = nextState;
678	
679	    if (terminalStatus !== undefined) {
680	      return {
681	        status: terminalStatus,
682	        state,
683	        tracePath: trace.path,
684	        iterations: iteration,
685	      };
686	    }
687	  }
688	
689	  return {
690	    status: 'iteration_limit',
691	    state,
692	    tracePath: trace.path,
693	    iterations: maxIterations,
694	  };
