442	async function resolveApproval(
443	  initialProposal: CandidateProposal,
444	  state: AgentState,
445	  evaluation: EvaluationResult,
446	  policy: PolicyDecision,
447	  approve: OrchestrationDependencies['approve'],
448	  searchResults: string[],
449	): Promise<{
450	  proposals: CandidateProposal[];
451	  proposal: CandidateProposal;
452	  decision: ApprovalDecision;
453	  decisions: ApprovalDecision[];
454	}> {
455	  const proposals = [initialProposal];
456	  const decisions: ApprovalDecision[] = [];
457	  let proposal = initialProposal;
458	
459	  for (let attempt = 0; attempt <= MAX_APPROVAL_ALTERNATIVES; attempt += 1) {
460	    const alternatives = allowedAlternatives(state, evaluation, policy);
461	    const decision = await approve({
462	      state,
463	      evaluation,
464	      policy,
465	      proposal: structuredClone(proposal),
466	      allowedAlternatives: [...alternatives],
467	    });
468	    decisions.push(decision);
469	    if (decision.kind !== 'alternative') return { proposals, proposal, decision, decisions };
470	    if (!alternatives.includes(decision.action)) {
471	      const rejection: ApprovalDecision = {
472	        kind: 'reject',
473	        reason: `${decision.action} is not a permitted alternative.`,
474	      };
475	      decisions.push(rejection);
476	      return {
477	        proposals,
478	        proposal,
479	        decision: rejection,
480	        decisions,
481	      };
482	    }
483	    proposal = repeatedFailureProposal(
484	      await selectCandidate(decision.action, state, searchResults),
485	      state,
486	    );
487	    proposals.push(proposal);
488	  }
489	
490	  const rejection: ApprovalDecision = {
491	    kind: 'reject',
492	    reason: 'Too many alternative selections.',
493	  };
494	  decisions.push(rejection);
495	  return {
496	    proposals,
497	    proposal,
498	    decision: rejection,
499	    decisions,
500	  };
501	}
