 65	export function buildWorkerContext(state: AgentState): WorkerContext {
 66	  const evidence = state.evidence;
 67	  const context: WorkerContext = {
 68	    validationGeneration: evidence?.validationGeneration ?? 0,
 69	    goal: bounded(state.currentGoal, 300),
 70	    clarifications: [],
 71	    findings: [],
 72	    failures: [],
 73	    remainingCalls: {
 74	      codex: Math.max(0, MAX_CODEX_CALLS - state.codexCalls),
 75	      claude: Math.max(0, MAX_CLAUDE_CALLS - state.claudeCalls),
 76	    },
 77	    ...(evidence && (
 78	      evidence.clarifications.length > MAX_WORKER_CONTEXT_ITEMS ||
 79	      evidence.findings.length > MAX_WORKER_CONTEXT_ITEMS ||
 80	      evidence.failures.length > MAX_WORKER_CONTEXT_ITEMS
 81	    ) ? { truncated: true } : {}),
 82	  };
 83	  if (!evidence) return context;
 84	
 85	  if (evidence.validation) {
 86	    context.validation = {
 87	      ...evidence.validation,
 88	      script: bounded(evidence.validation.script, 200),
 89	      summary: bounded(evidence.validation.summary),
 90	    };
 91	  }
 92	  if (evidence.worker) {
 93	    context.previousWorker = {
 94	      ...evidence.worker,
 95	      summary: bounded(evidence.worker.summary, 500),
 96	      modifiedFiles: evidence.worker.modifiedFiles
 97	        .map(safePath).filter((value): value is string => value !== undefined)
 98	        .slice(0, MAX_WORKER_CONTEXT_ITEMS),
 99	    };
100	  }
101	
102	  // Keep the newest user answer and validation result ahead of older findings.
103	  for (const item of evidence.clarifications.slice(-MAX_WORKER_CONTEXT_ITEMS).reverse()) {
104	    const next = { iteration: item.iteration, text: bounded(item.text) };
105	    context.clarifications.push(next);
106	    if (!fits(context)) {
107	      context.clarifications.pop();
108	      context.truncated = true;
109	    }
110	  }
111	  for (const item of evidence.failures.slice(-MAX_WORKER_CONTEXT_ITEMS).reverse()) {
112	    const next = { iteration: item.iteration, action: item.action, summary: bounded(item.summary, 500) };
113	    context.failures.push(next);
114	    if (!fits(context)) {
115	      context.failures.pop();
116	      context.truncated = true;
117	    }
118	  }
119	  for (const item of evidence.findings.slice(-MAX_WORKER_CONTEXT_ITEMS).reverse()) {
120	    const next: EvidenceFinding = {
121	      iteration: item.iteration,
122	      source: item.source,
123	      paths: item.paths.map(safePath).filter((value): value is string => value !== undefined)
124	        .slice(0, MAX_WORKER_CONTEXT_ITEMS),
125	      ...(item.excerpt === undefined ? {} : { excerpt: bounded(item.excerpt) }),
126	    };
127	    if (item.source === 'read' && next.paths.length === 0) {
128	      context.truncated = true;
129	      continue;
130	    }
131	    context.findings.push(next);
132	    if (!fits(context)) {
133	      context.findings.pop();
134	      context.truncated = true;
135	    }
136	  }
137	  if (!fits(context)) throw new Error('Worker context exceeds its size limit.');
138	  return context;
139	}
