513	export async function runOrchestration(
514	  initialState: AgentState,
515	  dependencies: OrchestrationDependencies,
516	  options: OrchestrationOptions = {},
517	): Promise<OrchestrationResult> {
518	  const maxIterations = options.maxIterations ?? MAX_ORCHESTRATION_ITERATIONS;
519	  if (!Number.isInteger(maxIterations) || maxIterations < 1 || maxIterations > MAX_ORCHESTRATION_ITERATIONS) {
520	    throw new Error(`Iteration limit must be between 1 and ${MAX_ORCHESTRATION_ITERATIONS}.`);
521	  }
522	
523	  const trace = await createOrchestrationTrace(initialState.repo.root);
524	  const execute = dependencies.execute ?? executeCandidate;
525	  const inspect = dependencies.inspect ?? inspectRepo;
526	  let state = initialState;
527	  let searchResults: string[] = [];
528	
529	  for (let iteration = 1; iteration <= maxIterations; iteration += 1) {
530	    state = { ...state, iteration };
531	    if (state.evidence?.repoRefreshRequired) {
532	      try {
533	        const refreshed = await inspect(state.repo.root);
534	        state = {
535	          ...state,
536	          repo: refreshed,
537	          filesModified: modifiedFiles(refreshed),
538	          evidence: { ...state.evidence, repoRefreshRequired: false },
539	          observations: [...state.observations, 'Repository inspection recovered after a worker attempt.'],
540	        };
541	      } catch {
542	        // Only ASK_USER remains available until a later inspection succeeds.
543	      }
544	    }
545	    const stateBefore = state;
546	    const evaluation = await dependencies.evaluate(state);
547	    const policy = applyPolicy(state, evaluation.assessment);
548	    const selected = repeatedFailureProposal(
549	      await selectCandidate(policy.selected, state, searchResults),
550	      state,
551	    );
552	    const approval = await resolveApproval(
553	      selected,
554	      state,
555	      evaluation,
556	      policy,
557	      dependencies.approve,
558	      searchResults,
559	    );
560	    const { proposal } = approval;
561	    let { decision } = approval;
562	    if (decision.kind === 'approve') {
563	      const blockedRepeat = state.failedApproaches.includes(proposalSignature(proposal, state));
564	      const exhaustedCodex = proposal.action === 'CALL_CODEX' && state.codexCalls >= MAX_CODEX_CALLS;
565	      const exhaustedClaude = proposal.action === 'CALL_CLAUDE' && state.claudeCalls >= MAX_CLAUDE_CALLS;
566	      if (blockedRepeat || exhaustedCodex || exhaustedClaude ||
567	        (state.evidence?.repoRefreshRequired && proposal.action !== 'ASK_USER')) {
568	        decision = {
569	          kind: 'reject',
570	          reason: blockedRepeat
571	            ? 'The resolved candidate already failed with the same relevant evidence.'
572	            : 'Repository inspection or a worker call limit prevents execution.',
573	        };
574	        approval.decisions.push(decision);
575	      }
576	    }
577	    let toolResult: ToolResult | null = null;
578	    let nextState = state;
579	    let terminalStatus: Extract<OrchestrationStatus, 'finished' | 'stopped'> | undefined;
580	
581	    if (decision.kind === 'stop') {
582	      terminalStatus = 'stopped';
583	      nextState = {
584	        ...state,
585	        observations: [...state.observations, stopObservation(decision)],
586	        currentGoal: 'Run stopped by user without claiming completion.',
587	      };
588	    } else if (decision.kind === 'reject') {
589	      nextState = {
590	        ...state,
591	        observations: [...state.observations, rejectionObservation(decision)],
592	        currentGoal: 'Choose a permitted alternative after user rejection.',
593	      };
594	    } else if (proposal.action === 'ASK_USER') {
595	      const information = truncateText(
596	        (await dependencies.askForInformation(state)).trim(),
597	        MAX_OBSERVATION_LENGTH,
598	      );
599	      nextState = withClarification({
600	        ...state,
601	        observations: [
602	          ...state.observations,
603	          information ? `User supplied information: ${information}` : 'User supplied no additional information.',
604	        ],
605	        currentGoal: 'Reassess the task with the user response.',
606	      }, information);
607	    } else if (proposal.action === 'FINISH') {
608	      terminalStatus = 'finished';
609	      const completionObservation = policy.selected === 'FINISH'
610	        ? 'User approved completion.'
611	        : 'User explicitly overrode completion confidence after passing validation.';
612	      nextState = {
613	        ...state,
614	        observations: [...state.observations, completionObservation],
615	        currentGoal: 'Task complete.',
616	      };
617	    } else {
618	      toolResult = await safelyExecute(proposal, execute);
619	      if (proposal.action === 'SEARCH_REPO' && toolResult.ok) searchResults = toolResult.files;
620	      let refreshedRepo: RepoSnapshot | undefined;
621	      let refreshFailed = false;
622	      if (isCodingAgentProposal(proposal)) {
623	        try {
624	          refreshedRepo = await inspect(state.repo.root);
625	        } catch {
626	          refreshFailed = true;
627	          toolResult = {
628	            ...toolResult,
629	            ok: false,
630	            output: `${toolResult.output}\nUnable to inspect the repository after ${codingAgentName(proposal)} execution.`,
631	          };
632	        }
633	      }
634	      nextState = applyToolResult(state, proposal, toolResult, refreshedRepo, refreshFailed);
635	    }
636	
637	    const reachedLimit = terminalStatus === undefined && iteration === maxIterations;
638	    if (reachedLimit) {
639	      nextState = {
640	        ...nextState,
641	        observations: [...nextState.observations, `Stopped at the ${maxIterations}-iteration limit.`],
642	        currentGoal: 'Ask the user how to continue after the iteration limit.',
643	      };
644	    }
645	
646	    await appendOrchestrationTrace(trace, {
647	      iteration,
648	      stateBefore,
649	      evaluation,
650	      policy,
651	      proposal: { considered: approval.proposals, selected: structuredClone(proposal) },
652	      approval: { ...decision, history: approval.decisions },
653	      toolInput: decision.kind === 'stop' ? null : proposal.input,
654	      toolResult,
655	      stateAfter: nextState,
656	      ...(isCodingAgentProposal(proposal) ? {
657	        workerRequest: {
658	          id: proposalSignature(proposal, state),
659	          evidenceRevision: state.evidence?.revision ?? 0,
660	          validationGeneration: state.evidence?.validationGeneration ?? 0,
661	          clarificationIterations: proposal.input.context.clarifications.map((item) => item.iteration),
662	          findingPaths: proposal.input.context.findings.flatMap((item) => item.paths).slice(0, 8),
663	          retryReason: decision.kind !== 'approve'
664	            ? 'Worker proposal was not executed.'
665	            : state.evidence?.validation?.passed === false
666	              ? 'Repair after failed independent validation.'
667	              : state.evidence?.worker?.ok === false
668	                ? state.evidence.worker.agent !== (proposal.action === 'CALL_CODEX' ? 'codex' : 'claude')
669	                  ? 'User selected another agent after a failed worker.'
670	                  : state.evidence.revision > state.evidence.worker.evidenceRevision
671	                    ? `New ${state.evidence.lastRevisionSource ?? 'repository'} evidence after a failed worker.`
672	                    : 'Approved worker request after prior failure.'
673	                : 'Approved worker request.',
674	        },
675	      } : {}),
676	    });
677	    state = nextState;
678	
679	    if (terminalStatus !== undefined) {
680	      return {
681	        status: terminalStatus,
682	        state,
683	        tracePath: trace.path,
684	        iterations: iteration,
685	      };
686	    }
687	  }
688	
689	  return {
690	    status: 'iteration_limit',
691	    state,
692	    tracePath: trace.path,
693	    iterations: maxIterations,
694	  };
695	}
