158	export function assertWorkerContext(value: unknown): asserts value is WorkerContext {
159	  if (!isRecord(value)) {
160	    throw new Error('Worker context is malformed or exceeds its limits.');
161	  }
162	  let serialized: string;
163	  try {
164	    serialized = JSON.stringify(value);
165	  } catch {
166	    throw new Error('Worker context is malformed or exceeds its limits.');
167	  }
168	  if (
169	    serialized.length > MAX_WORKER_CONTEXT_LENGTH ||
170	    redactSensitiveText(serialized) !== serialized ||
171	    !hasOnlyKeys(value, [
172	      'validationGeneration', 'goal', 'clarifications', 'findings', 'failures',
173	      'remainingCalls', 'validation', 'previousWorker', 'truncated',
174	    ]) ||
175	    !isIteration(value.validationGeneration) ||
176	    typeof value.goal !== 'string' || value.goal.length > 300 ||
177	    !Array.isArray(value.clarifications) || value.clarifications.length > MAX_WORKER_CONTEXT_ITEMS ||
178	    !value.clarifications.every((item) => isRecord(item) &&
179	      hasOnlyKeys(item, ['iteration', 'text']) && isIteration(item.iteration) &&
180	      typeof item.text === 'string' && item.text.length <= MAX_WORKER_EXCERPT_LENGTH) ||
181	    !Array.isArray(value.findings) || value.findings.length > MAX_WORKER_CONTEXT_ITEMS ||
182	    !value.findings.every((item) => isRecord(item) &&
183	      hasOnlyKeys(item, ['iteration', 'source', 'paths', 'excerpt']) &&
184	      isIteration(item.iteration) &&
185	      typeof item.source === 'string' && ['search', 'read', 'diagnostic'].includes(item.source) &&
186	      Array.isArray(item.paths) && item.paths.length <= MAX_WORKER_CONTEXT_ITEMS &&
187	      item.paths.every((entry) => typeof entry === 'string' && safePath(entry) === entry) &&
188	      (item.excerpt === undefined ||
189	        (typeof item.excerpt === 'string' && item.excerpt.length <= MAX_WORKER_EXCERPT_LENGTH))) ||
190	    !Array.isArray(value.failures) || value.failures.length > MAX_WORKER_CONTEXT_ITEMS ||
191	    !value.failures.every((item) => isRecord(item) &&
192	      hasOnlyKeys(item, ['iteration', 'action', 'summary']) &&
193	      isIteration(item.iteration) && ACTIONS.some((action) => action === item.action) &&
194	      typeof item.summary === 'string' &&
195	      item.summary.length <= MAX_WORKER_EXCERPT_LENGTH) ||
196	    !isRecord(value.remainingCalls) ||
197	    !hasOnlyKeys(value.remainingCalls, ['codex', 'claude']) ||
198	    (value.truncated !== undefined && typeof value.truncated !== 'boolean') ||
199	    !isRemainingCallCount(value.remainingCalls.codex, MAX_CODEX_CALLS) ||
200	    !isRemainingCallCount(value.remainingCalls.claude, MAX_CLAUDE_CALLS) ||
201	    (value.validation !== undefined && (
202	      !isRecord(value.validation) ||
203	      !hasOnlyKeys(value.validation, [
204	        'iteration', 'generation', 'script', 'exitCode', 'timedOut', 'passed', 'summary',
205	      ]) ||
206	      !isIteration(value.validation.iteration) ||
207	      !isIteration(value.validation.generation) ||
208	      !isExitCode(value.validation.exitCode) ||
209	      typeof value.validation.script !== 'string' ||
210	      value.validation.script.length > 200 ||
211	      typeof value.validation.summary !== 'string' ||
212	      value.validation.summary.length > MAX_WORKER_EXCERPT_LENGTH ||
213	      typeof value.validation.passed !== 'boolean' ||
214	      typeof value.validation.timedOut !== 'boolean'
215	    )) ||
216	    (value.previousWorker !== undefined && (
217	      !isRecord(value.previousWorker) ||
218	      !hasOnlyKeys(value.previousWorker, [
219	        'iteration', 'agent', 'evidenceRevision', 'exitCode', 'timedOut',
220	        'ok', 'summary', 'modifiedFiles',
221	      ]) ||
222	      !isIteration(value.previousWorker.iteration) ||
223	      !Number.isInteger(value.previousWorker.evidenceRevision) ||
224	      !isExitCode(value.previousWorker.exitCode) ||
225	      typeof value.previousWorker.agent !== 'string' ||
226	      !['codex', 'claude'].includes(value.previousWorker.agent) ||
227	      typeof value.previousWorker.ok !== 'boolean' ||
228	      typeof value.previousWorker.timedOut !== 'boolean' ||
229	      typeof value.previousWorker.summary !== 'string' ||
230	      value.previousWorker.summary.length > MAX_WORKER_EXCERPT_LENGTH ||
231	      !Array.isArray(value.previousWorker.modifiedFiles) ||
232	      value.previousWorker.modifiedFiles.length > MAX_WORKER_CONTEXT_ITEMS ||
233	      value.previousWorker.modifiedFiles.some((entry) => safePath(entry) !== entry)
234	    ))
235	  ) throw new Error('Worker context is malformed or exceeds its limits.');
236	}
